import math

def distance(a, b):
    return math.sqrt(sum((x - y) ** 2 for x, y in zip(a, b)))

def predict(train, point, k=3):
    ranked = sorted(train, key=lambda item: distance(item[0], point))
    labels = [label for _, label in ranked[:k]]
    return max(sorted(set(labels)), key=labels.count)

